<?php declare(strict_types=1);$base=config('app.base_path'); ?><div class="page-header"><div><h1><?= htmlspecialchars((string)$record['name'],ENT_QUOTES,'UTF-8') ?></h1><p><?= htmlspecialchars((string)$record['stay_type'],ENT_QUOTES,'UTF-8') ?> · <?= htmlspecialchars((string)($record['provider_name']??''),ENT_QUOTES,'UTF-8') ?></p></div><div class="page-actions"><a class="btn btn-secondary" href="<?= $base ?>/tourism/stays/<?= (int)$record['id'] ?>/edit">Edit</a></div></div><div class="card"><div class="stay-meta"><div><strong>Destination</strong><span><?= htmlspecialchars((string)($record['destination_name']??'Not linked'),ENT_QUOTES,'UTF-8') ?></span></div><div><strong>Location</strong><span><?= htmlspecialchars(trim((string)($record['city']??'').' / '.(string)($record['district']??''),' /'),ENT_QUOTES,'UTF-8') ?></span></div><div><strong>Coordinates</strong><span><?= $record['latitude']!==null?htmlspecialchars($record['latitude'].' , '.$record['longitude'],ENT_QUOTES,'UTF-8'):'Not set' ?></span></div><div><strong>Status</strong><span><?= htmlspecialchars((string)$record['status'],ENT_QUOTES,'UTF-8') ?></span></div><div><strong>Starting Price</strong><span><?= $record['starting_price_per_night']!==null?'₹'.number_format((float)$record['starting_price_per_night'],2).'/night':'Not set' ?></span></div></div><hr><p><?= nl2br(htmlspecialchars((string)($record['description']??'No description.'),ENT_QUOTES,'UTF-8')) ?></p></div><div class="card"><div class="page-header"><div><h2>Room Types</h2><p>Define room inventory and nightly pricing. Availability/booking comes in the next phase.</p></div></div><form method="post" action="<?= $base ?>/tourism/stays/<?= (int)$record['id'] ?>/rooms"><div class="form-grid"><div><label>Name *</label><input name="name" required placeholder="Deluxe Room"></div><div><label>Bed Type</label><input name="bed_type" placeholder="King Bed"></div><div><label>Max Guests</label><input type="number" min="1" name="max_guests" value="2"></div><div><label>Quantity</label><input type="number" min="1" name="quantity" value="1"></div><div><label>Price / Night (₹)</label><input type="number" step="0.01" min="0" name="price_per_night" value="0"></div><div><label>Status</label><select name="status"><option>Active</option><option>Inactive</option></select></div><div class="full"><label>Description</label><textarea name="description" rows="2"></textarea></div></div><button class="btn btn-primary">Add Room Type</button></form><div class="table-responsive" style="margin-top:18px"><table class="table"><thead><tr><th>Room</th><th>Bed</th><th>Guests</th><th>Qty</th><th>Price</th><th>Status</th><th></th></tr></thead><tbody><?php if(empty($rooms)): ?><tr><td colspan="7"><div class="empty-state">No room types yet.</div></td></tr><?php else:foreach($rooms as $r): ?><tr><td><strong><?= htmlspecialchars((string)$r['name'],ENT_QUOTES,'UTF-8') ?></strong><br><small><?= htmlspecialchars((string)($r['description']??''),ENT_QUOTES,'UTF-8') ?></small></td><td><?= htmlspecialchars((string)($r['bed_type']??'—'),ENT_QUOTES,'UTF-8') ?></td><td><?= (int)$r['max_guests'] ?></td><td><?= (int)$r['quantity'] ?></td><td>₹<?= number_format((float)$r['price_per_night'],2) ?></td><td><?= htmlspecialchars((string)$r['status'],ENT_QUOTES,'UTF-8') ?></td><td><form method="post" action="<?= $base ?>/tourism/stays/<?= (int)$record['id'] ?>/rooms/<?= (int)$r['id'] ?>/delete"><button class="link-button danger" onclick="return confirm('Move this room type to Trash?')">Delete</button></form></td></tr><?php endforeach;endif;?></tbody></table></div></div><style>.stay-meta{display:grid;grid-template-columns:repeat(5,1fr);gap:14px}.stay-meta>div{padding:14px;border:1px solid #e5e7eb;border-radius:12px}.stay-meta strong,.stay-meta span{display:block}.stay-meta strong{font-size:12px;color:#64748b;text-transform:uppercase}.stay-meta span{margin-top:6px}.form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.form-grid label{display:block;font-weight:600;margin-bottom:6px}.form-grid input,.form-grid select,.form-grid textarea{width:100%;box-sizing:border-box}.full{grid-column:1/-1}@media(max-width:800px){.stay-meta{grid-template-columns:1fr 1fr}}@media(max-width:600px){.form-grid{grid-template-columns:1fr}.full{grid-column:auto}}</style>
